    TwistExpander_Achernar_Arx::SEED_A(PARAMS_SEED);

    TwistExpander_Achernar_Arx::SEED_B(PARAMS_SEED);

    TwistExpander_Achernar_Arx::SEED_C(PARAMS_SEED);

